macro_rules! deps {
    () => {
        Id!();
        Item!();
        MessageLevel!();
        Step!();
        Count!();
        Unit!();
    };
}

macro_rules! Progress {
    () => {
        deps!();
        # [doc = " A trait for describing non-hierarchical progress."] # [doc = ""] # [doc = " It differs by not being able to add child progress dynamically, but in turn is object safe. It's recommended to"] # [doc = " use this trait whenever there is no need to add child progress, at the leaf of a computation."] pub trait Progress : Count + Send + Sync { # [doc = " Initialize the Item for receiving progress information."] # [doc = ""] # [doc = " If `max` is `Some(…)`, it will be treated as upper bound. When progress is [set(…)](./struct.Item.html#method.set)"] # [doc = " it should not exceed the given maximum."] # [doc = " If `max` is `None`, the progress is unbounded. Use this if the amount of work cannot accurately"] # [doc = " be determined in advance."] # [doc = ""] # [doc = " If `unit` is `Some(…)`, it is used for display purposes only. See `prodash::Unit` for more information."] # [doc = ""] # [doc = " If both `unit` and `max` are `None`, the item will be reset to be equivalent to 'uninitialized'."] # [doc = ""] # [doc = " If this method is never called, this `Progress` instance will serve as organizational unit, useful to add more structure"] # [doc = " to the progress tree (e.g. a headline)."] # [doc = ""] # [doc = " **Note** that this method can be called multiple times, changing the bounded-ness and unit at will."] fn init (& mut self , max : Option < progress :: Step > , unit : Option < Unit >) ; # [doc = " Returns the (cloned) unit associated with this Progress"] fn unit (& self) -> Option < Unit > { None } # [doc = " Returns the maximum about of items we expect, as provided with the `init(…)` call"] fn max (& self) -> Option < progress :: Step > { None } # [doc = " Set the maximum value to `max` and return the old maximum value."] fn set_max (& mut self , _max : Option < progress :: Step >) -> Option < progress :: Step > { None } # [doc = " Set the name of the instance, altering the value given when crating it with `add_child(…)`"] # [doc = " The progress is allowed to discard it."] fn set_name (& mut self , name : String) ; # [doc = " Get the name of the instance as given when creating it with `add_child(…)`"] # [doc = " The progress is allowed to not be named, thus there is no guarantee that a previously set names 'sticks'."] fn name (& self) -> Option < String > ; # [doc = " Get a stable identifier for the progress instance."] # [doc = " Note that it could be [unknown][crate::progress::UNKNOWN]."] fn id (& self) -> Id ; # [doc = " Create a `message` of the given `level` and store it with the progress tree."] # [doc = ""] # [doc = " Use this to provide additional,human-readable information about the progress"] # [doc = " made, including indicating success or failure."] fn message (& self , level : MessageLevel , message : String) ; # [doc = " Create a message providing additional information about the progress thus far."] fn info (& self , message : String) { self . message (MessageLevel :: Info , message) } # [doc = " Create a message indicating the task is done successfully"] fn done (& self , message : String) { self . message (MessageLevel :: Success , message) } # [doc = " Create a message indicating the task failed"] fn fail (& self , message : String) { self . message (MessageLevel :: Failure , message) } # [doc = " A shorthand to print throughput information"] fn show_throughput (& self , start : Instant) { let step = self . step () ; match self . unit () { Some (unit) => self . show_throughput_with (start , step , unit , MessageLevel :: Info) , None => { let elapsed = start . elapsed () . as_secs_f32 () ; let steps_per_second = (step as f32 / elapsed) as progress :: Step ; self . info (format ! ("done {} items in {:.02}s ({} items/s)" , step , elapsed , steps_per_second)) } } ; } # [doc = " A shorthand to print throughput information, with the given step and unit, and message level."] fn show_throughput_with (& self , start : Instant , step : progress :: Step , unit : Unit , level : MessageLevel) { use std :: fmt :: Write ; let elapsed = start . elapsed () . as_secs_f32 () ; let steps_per_second = (step as f32 / elapsed) as progress :: Step ; let mut buf = String :: with_capacity (128) ; let unit = unit . as_display_value () ; let push_unit = | buf : & mut String | { buf . push (' ') ; let len_before_unit = buf . len () ; unit . display_unit (buf , step) . ok () ; if buf . len () == len_before_unit { buf . pop () ; } } ; buf . push_str ("done ") ; unit . display_current_value (& mut buf , step , None) . ok () ; push_unit (& mut buf) ; buf . write_fmt (format_args ! (" in {:.02}s (" , elapsed)) . ok () ; unit . display_current_value (& mut buf , steps_per_second , None) . ok () ; push_unit (& mut buf) ; buf . push_str ("/s)") ; self . message (level , buf) ; } }
    };
}

Progress!();